import hashlib, itertools, json
target='961917cf67c78829124fca7b4e3472e5'
fields={
 'vendor':'Recovery Storage 000001',
 'currency':'USD',
 'sku':'recovery-shelf-000001',
 'unit':'8000000',
 'unit_total_cents':'8000000',
 'price':'8000000',
 'tax':'true','delivery':'true'
}
seps=['','|',':','-','_','/',',',';',' ']
patterns=[]
vals=list(fields.values())
keys=list(fields.keys())
# permutations of subsets up to 4 fields
for r in range(1,5):
  for combo in itertools.permutations(vals,r):
    for sep in seps:
      patterns.append(sep.join(combo))
# key=value patterns
for r in range(1,5):
  for combo in itertools.permutations(keys,r):
    for sep in seps:
      patterns.append(sep.join(f'{k}={fields[k]}' for k in combo))
      patterns.append(sep.join(f'{k}:{fields[k]}' for k in combo))
# json dumps variants
for sort in [True,False]:
  for sep in [None,(',',':')]:
    try:
      s=json.dumps({k:fields[k] for k in ['vendor','currency','sku','unit_total_cents','tax','delivery']}, sort_keys=sort, separators=sep) if sep else json.dumps({k:fields[k] for k in ['vendor','currency','sku','unit_total_cents','tax','delivery']}, sort_keys=sort)
      patterns.append(s)
    except: pass
for s in set(patterns):
    if hashlib.md5(s.encode()).hexdigest()==target:
        print('MATCH',repr(s)); break
else:
    print('no match',len(set(patterns)))
EOF"}
